import * as echarts from "echarts/core";

// import echarts necessary components
import {
  TitleComponent,
  TooltipComponent,
  GridComponent,
  // DatasetComponent,
  // TransformComponent,
  LegendComponent
} from "echarts/components";

import { LabelLayout, UniversalTransition } from "echarts/features";

// import Canvas Renderer, note that CanvasRenderer or SVGRenderer is required
import { CanvasRenderer } from "echarts/renderers";

// register necessary components
echarts.use([
  TitleComponent,
  TooltipComponent,
  GridComponent,
  LegendComponent,
  LabelLayout,
  UniversalTransition,
  CanvasRenderer
]);
export { echarts };

export function useEcharts(elementRef, options) {
  const chart = ref(null);
  // resize chart
  const resizeChart = () => {
    chart.value?.resize();
  };
  // clean up resources
  const dispose = () => {
    window.removeEventListener("resize", resizeChart);
    if (chart.value) {
      chart.value.dispose();
      chart.value = null;
    }
  };
  watch(elementRef, () => {
    if (elementRef.value) {
      chart.value = echarts.init(elementRef.value);
    }
  });
  watch(() => [chart.value, options.value], () => {
    if (!chart.value || !options.value) return;
    chart.value.setOption(options.value);
  })
  onMounted(() => {
    window.addEventListener("resize", resizeChart);
  });
  onUnmounted(dispose);
  return {
    chart,
  };
}

